  const cb = [...cols.keys()].filter((k) => k !== UNSORTED);
  const w = ra.map((r) => cb.map((c) => table.get(`${r}${c}`) ?? 0));
  const kept = kept0 + (ra.length && cb.length ? bestMatch(w) : 0);
