    rand_index: total ? same / total : 1,
    adjusted_rand_index: ids.length ? ari : 1,
    notes_moved_share: ids.length ? (ids.length - kept) / ids.length : 0,
    notes_moved: ids.length - kept,
    notes: ids.length,
    pairs: total
