  md.push("## Summary", "");
  for (const i of top) md.push(`- **${i.title}** (${stats.get(i.id).n_of_N} participants, ${stats.get(i.id).confidence} confidence${i.severity ? `, ${i.severity}` : ""})`);
  md.push("");
